+  ["DWH", "interno"],
+  ["demo-facturas", "interno"],
+  ["demo-inventario", "interno"],
+]);
+
+export function clasificacionDeSistema(sistema) {
+  const clase = CLASE_POR_SISTEMA.get(sistema);
+  if (clase === undefined) throw new Error(`Sistema no registrado: ${sistema}`);
